\label{thm:main-thm}
Under Assumptions \ref{assump1} and \ref{assump2}, let $A^*$ be $k$-sparse and $\ensuremath{\mathcal{A}}$ be as in \eqref{eq:Astar_l1ball}. There exist constants $c_1, c_2, c_3, c' > 1$ such that the following is true. Let $\delta \in (0,1)$,

\begin{align*}
&L=J^4(A^*) k^2 \cdot \log \left(\frac{n^2}{k}\right) \cdot \max \left\{{s,\log \left(\frac{n}{\delta}\right)}\right\} \text{ and,}\\
&\lambda = 2\left(\sqrt{n}+n^{1/4} \log^{1/4} \left(\frac{T}{\delta}\right)+2^{1/2} \log^{1/2} \left(\frac{T}{\delta}\right)\right).
\end{align*} 


It holds that if  


\begin{align*}
T \ge c' \cdot L \log^2 \left( \frac{n \cdot L}{\delta}\right), \ \  r = c_3 J(A^*) \sqrt{\log \left(\frac{Tn}{\delta}\right)},
\end{align*}

then with probability at least $1-\delta$, any solution $(\widehat{A}, \widehat{U})$ of \eqref{eq:l12-ls-pen} satisfies

\begin{align*}
&\big\|{\widehat{A}-A^*}\big\|_F^2+\frac{1}{T}\big\|{(\widehat{U}-U^*) D}\big\|_{F}^2 \\ 
&\le c_1\frac{J^2(A^*) k\log \left(\frac{Tn}{\delta}\right)\log \left(\frac{n}{\delta}\right)}{T}\\
&+c_2 \max \left\{{n,\log^2\left(\frac{T}{\delta}\right)}\right\}\frac{s}{T}.
\end{align*}

\label{thm:psd-sup}
Let $\ensuremath{\mathcal{M}}$ be a set of matrices and $\eta$ be a vector with independent, zero-mean, $R$-subgaussian entries with unit variance. Let,
\begin{align*}
F &\coloneq \ensuremath{\gamma_{2}} \left(\ensuremath{\mathcal{M}},\big\|{\cdot}\big\|_2\right) \left[\ensuremath{\gamma_{2}} \left(\ensuremath{\mathcal{M}},\big\|{\cdot}\big\|_2\right)+d_F(\ensuremath{\mathcal{M}})\right]+d_F(\ensuremath{\mathcal{M}})d_2(\ensuremath{\mathcal{M}}),\\
V &\coloneq d_2(\ensuremath{\mathcal{M}})\left[\ensuremath{\gamma_{2}} \left(\ensuremath{\mathcal{M}},\big\|{\cdot}\big\|_2\right)+d_F(\ensuremath{\mathcal{M}})\right], \text{ and, } U \coloneq d^2_2(\ensuremath{\mathcal{M}}).
\end{align*}
There exist constants $c_1,c_2>0$ depending only on $R$ such that for any $t > 0$,
\begin{align*}
\ensuremath{\mathbb{P}} \left(\sup_{M \in \ensuremath{\mathcal{M}}} \ensuremath{\left | \big\|{M\eta}\big\|_2^2-\ensuremath{\mathbb{E}} \left[\big\|{M\eta}\big\|_2^2\right] \right |} \ge c_1 F+t\right) 
\le 2\exp \left(-c_2\min\left\{{\frac{t^2}{V},\frac{t}{U}}\right\}\right).
\end{align*}

\label{thm:bounded-func-conc}
Consider $X = (X_1,X_2,\dots,X_n)$ independent random variables with $X_i \in [a,b]$ almost surely. Let $f:\ensuremath{\mathbb{R}}^{n} \rightarrow \ensuremath{\mathbb{R}}$ be convex and $R$-Lipschitz with respect to $\big\|{\cdot}\big\|_2$ norm. Then $\forall t \ge 0$
\[\ensuremath{\mathbb{P}} \left(|f(X)-\ensuremath{\mathbb{E}} f(X)|\ge t\right) \le 2\exp \left(\frac{-t^2}{2R^2(b-a)^2}\right).\]

\label{thm:self-nrml-mart}
Let $(\ensuremath{\mathcal{F}}_t)_{t=1}^\infty$ be a filtration. Let $(\eta_t)_{t=1}^\infty$ be a real valued stochastic process such that $\eta_t$ is $\ensuremath{\mathcal{F}}_t$ measurable, and $\eta_{t+1}$ is $R$-sub-Gaussian conditioned on $\ensuremath{\mathcal{F}}_{t}$. Let $(X_t)_{t=1}^\infty$ be a stochastic process where $X_t \in \ensuremath{\mathbb{R}}^d$ is $\ensuremath{\mathcal{F}}_t$ measurable. Let $V \in \ensuremath{\mathbb{R}}^{n \times n}$ be a p.d matrix and for $t \ge 1$, denote


\begin{align*}
\bar{V}_t = V+\sum_{s=1}^t X_s X_s^\top \ \text{ and } \
S_t = \sum_{s=1}^t \eta_{s+1} X_s.
\end{align*}



Then for any $\delta>0$, it holds with probability $\ge 1-\delta$ that for all $t \ge 1$, 


\begin{align*}
\big\|{S_t}\big\|^2_{\bar{V}_t^{-1}} \le 2R^2\log \left(\frac{\det(\bar{V}_t)^{1/2}\det(V)^{-1/2}}{\delta}\right)
\end{align*}
where $\big\|{S_t}\big\|_{\bar{V}_t^{-1}} = \sqrt{S_t^\top (\bar{V}_t^{-1}) S_t}$.

\label{lem:chi-sq-dev}
Let $X_1,X_2,\dots,X_d \stackrel{\mathclap{\normalfont\mbox{i.i.d.}}}{\sim} \mathcal{N}\left(0,1\right)$ and let $\mu = \left(\mu_1,\mu_2,\dots,\mu_d\right)$ be a non-negative vector. Define,
\begin{align*}
\xi = \sum_{i=1}^d \mu_i (X_i^2-1).
\end{align*}
Then it holds $\forall v \ge 0$,
\begin{align*}
\Pr \left(\xi \ge 2\big\|{\mu}\big\|_2\sqrt{v}+2\big\|{\mu}\big\|_\infty v\right) \le e^{-v}.
\end{align*}

\label{lem:main-inequ}
If $\lambda \ge 2  \max_{t \in \left\{{2,\dots,T}\right\}} \big\|{\eta_t}\big\|_2$, then


\begin{align}\label{eq:main-inequ}
\frac{1}{2} \big\|{\Delta Y' D}\big\|_F^2 &\le \Big\langle\Delta_A,\overline{E}DY^\top\Big\rangle+\frac{\lambda}{2} \Bigg(3\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}-\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}}}\big\|_{2,1}\Bigg).
\end{align}

\label{lem:all-unc-select}
There exists a constant $c > 1$ such that for any $\delta \in (0,1)$, and $r = cJ(A^*) \sqrt{\log \left(\frac{Tn}{\delta}\right)}$, it holds that

\begin{align*}
\ensuremath{\mathbb{P}}\left(\ensuremath{\ensuremath{\mathcal{E}}_{1b}}\right) \ge 1-\delta.
\end{align*}

\label{rem:support-cone}
Denote $\ensuremath{\mathcal{K}} = \operatorname{supp}(A^*)$. Since $\big\|{A^*}\big\|_{1,1} \ge \big\|{\widehat{A}}\big\|_{1,1}$, we obtain, 



\begin{align*}
\big\|{A^*}\big\|_{1,1} &\ge \big\|{\Delta_A+A^*}\big\|_{1,1}\\
&=\big\|{(\Delta_A)_{\ensuremath{\mathcal{K}}}+(A^*)_{\ensuremath{\mathcal{K}}}}\big\|_{1,1}+\big\|{(\Delta_A)_{\ensuremath{\mathcal{K}}^c}}\big\|_{1,1}\\
&\ge \big\|{(A^*)_{\ensuremath{\mathcal{K}}}}\big\|_{1,1}+\big\|{(\Delta_A)_{\ensuremath{\mathcal{K}}^c}}\big\|_{1,1}-\big\|{(\Delta_A)_{\ensuremath{\mathcal{K}}}}\big\|_{1,1}
\end{align*}

which implies

\begin{align*}
 \big\|{(\Delta_A)_{\ensuremath{\mathcal{K}}^c}}\big\|_{1,1} & \le \big\|{(\Delta_A)_{\ensuremath{\mathcal{K}}}}\big\|_{1,1}.
\end{align*}
So $\Delta_A \in \ensuremath{\mathcal{C}}_{\ensuremath{\mathcal{K}}}$ where,
\begin{align*}
\ensuremath{\mathcal{C}}_{\ensuremath{\mathcal{K}}} \coloneq \left\{{H \in \ensuremath{\mathbb{R}}^{n \times n}: \big\|{(H)_{\ensuremath{\mathcal{K}}^c}}\big\|_{1,1} \le \big\|{(H)_{\ensuremath{\mathcal{K}}}}\big\|_{1,1}}\right\}.
\end{align*}


Note that this implies, $\big\|{\Delta_A}\big\|_{1,1} \le 2\big\|{(\Delta_A)_{\ensuremath{\mathcal{K}}}}\big\|_{1,1} \le 2\sqrt{k} \big\|{\Delta_A}\big\|_F$ where $k= |\ensuremath{\mathcal{K}}|$. We denote $\widetilde{\ensuremath{\mathcal{C}}}_{\ensuremath{\mathcal{K}}} = \ensuremath{\mathcal{C}}_{\ensuremath{\mathcal{K}}} \cap \mathbb{S}_n$.

\label{lem:bnd-cross-trm}
For any $\delta \in (0,1)$,  we have
 $$\ensuremath{\mathbb{P}}\left(\ensuremath{\ensuremath{\mathcal{E}}_{4}}\right) \ge 1-\delta.$$

\label{rem:upper-st}
Note that,
\begin{align*}
T \ge cJ^4(A^*) k^2 \cdot \log \left(\frac{n^2}{k}\right) \cdot  \max \left\{{s,\log \left(\frac{n}{\delta}\right)}\right\} \log^2 \left( \frac{J^4(A^*) k^2 \cdot \log \left(\frac{n^2}{k}\right) \cdot \max \left\{{s,\log \left(\frac{n}{\delta}\right)}\right\} n}{\delta}\right)
\end{align*}
implies,
\begin{align*}
\frac{s}{T} \le \frac{1}{cJ^4(A^*) k^2 \cdot \log \left(\frac{n^2}{k}\right) \cdot \log^2 \left( \frac{ n}{\delta}\right)}
\end{align*}

Note that since $\widehat{A},\widehat{U}$ is the optimal solution and $A^*, \ensuremath{U^*}$ is a feasible solution, we get,
\begin{align*}
&\frac{1}{2} \big\|{\left(\overline{Y}-\widehat{A}Y-\widehat{U}\right) D}\big\|_F^2+\lambda \big\|{\widehat{U} D}\big\|_{2,1} \le \frac{1}{2} \big\|{\left(\overline{Y}-A^*Y-\ensuremath{U^*}\right) D}\big\|_F^2+\lambda \big\|{\ensuremath{U^*} D}\big\|_{2,1}
\end{align*}
which implies
\begin{align*}
&\frac{1}{2}\big\|{(A^*-\widehat{A})YD + \overline{E}D+(\ensuremath{U^*}-\widehat{U})D}\big\|_F^2 \le \frac{1}{2} \big\|{\overline{E}D}\big\|_F^2+ \left(\lambda \big\|{\ensuremath{U^*} D}\big\|_{2,1}-\lambda \big\|{\widehat{U} D}\big\|_{2,1}\right).
\end{align*}
Denoting $\Delta_A = \widehat{A}-A^*$ and $\Delta_U = \widehat{U}-U^*$  note that,
\begin{align*}
\Delta_A Y + \Delta_U = \underbrace{\ensuremath{\begin{bmatrix} \Delta_A & \Delta_U \end{bmatrix}}}_{\equiv \Delta} \underbrace{\ensuremath{\begin{bmatrix} Y \\ I \end{bmatrix}}}_{\equiv Y'} = \Delta Y'.
\end{align*}
Therefore, we get,
\begin{align*}
&\frac{1}{2} \big\|{(\Delta Y'-\overline{E})D}\big\|_F^2 \le \frac{1}{2} \big\|{\widehat{E}D}\big\|_F^2+ \left(\lambda \big\|{\ensuremath{U^*} D}\big\|_{2,1}-\lambda \big\|{\widehat{U} D}\big\|_{2,1}\right)\\
\end{align*}
which is equivalent to,
\begin{align*}
\frac{1}{2} \big\|{\Delta Y'D}\big\|_F^2 &\le \Big\langle\Delta Y',\overline{E}D\Big\rangle+ \left(\lambda \big\|{\ensuremath{U^*} D}\big\|_{2,1}-\lambda \big\|{\widehat{U} D}\big\|_{2,1}\right)\\
& = \Big\langle\Delta_A,\overline{E}DY^\top\Big\rangle+ \Big\langle\Delta_U,\overline{E}D\Big\rangle+ \lambda\left( \big\|{\ensuremath{U^*} D}\big\|_{2,1}-\big\|{\widehat{U} D}\big\|_{2,1}\right).
\end{align*}

Now note that


\begin{align*}
\Big\langle\Delta_U,\overline{E}D\Big\rangle &= \Big\langle\Delta_U D,\overline{E}\Big\rangle= \sum_{t=1}^{T-1} \Big\langleD_t(\widehat{u}_t-\ensuremath{u^*}_t),\eta_{t+1}\Big\rangle\\
& \le \sum_{t=1}^{T-1} \big\|{D_t(\widehat{u}_t-\ensuremath{u^*}_t)}\big\|_2 \big\|{\eta_{t+1}}\big\|_2 \le \left(\max_{t \in \left\{{2,\dots,T}\right\}} \big\|{\eta_t}\big\|_2\right)\big\|{\Delta_U D}\big\| \\
& \le \frac{\lambda}{2}\big\|{\Delta_U D}\big\|
\end{align*}\
where $\lambda \ge 2 \max_{t \in \left\{{2,\dots,T}\right\}} \big\|{\eta_t}\big\|_2$. Then we have,
\begin{align*}
&\Big\langle\Delta_U,\overline{E}D\Big\rangle +\lambda \left(\big\|{\ensuremath{U^*} D}\big\|_{2,1}- \big\|{\widehat{U} D}\big\|_{2,1}\right) \le \lambda \left(\frac{1}{2}\big\|{\Delta_U D}\big\|+\big\|{\ensuremath{U^*} D}\big\|_{2,1}- \big\|{\widehat{U} D}\big\|_{2,1}\right).
\end{align*}

By a decomposition over $\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}$ and $\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}$, we obtain
\begin{align*}
\big\|{\ensuremath{U^*} D}\big\|_{2,1}-\big\|{\widehat{U} D}\big\|_{2,1} &=\big\|{\ensuremath{U^*} D}\big\|_{2,1}-\big\|{\Delta_UD+ \ensuremath{U^*} D}\big\|_{2,1}\\
&=\big\|{(\ensuremath{U^*} D)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}-\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}+ (\ensuremath{U^*} D)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}-\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}}}\big\|_{2,1},
\end{align*}
which implies,
\begin{align*}
&\lambda \Big(\frac{1}{2} \big\|{\Delta_U D}\big\|_{2,1}+\big\|{\ensuremath{U^*} D}\big\|_{2,1}-\big\|{\hat{U}D}\big\|_{2,1}\Big)\\
&=\lambda \Bigg(\frac{1}{2} \big\|{\Delta_U D}\big\|_{2,1}+\big\|{(\ensuremath{U^*} D)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}-\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}+ (\ensuremath{U^*} D)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}-\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}}}\big\|_{2,1}\Bigg)\\
&\le  \lambda \Bigg(\frac{1}{2} \big\|{\Delta_U D}\big\|_{2,1}+\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}-\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}}}\big\|_{2,1}\Bigg)\\
&=  \frac{\lambda}{2} \Bigg(3\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}-\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}}}\big\|_{2,1}\Bigg).
\end{align*}

Therefore, if $\lambda \ge 2  \max_{t \in \left\{{2,\dots,T}\right\}} \big\|{\eta_t}\big\|_2$, then,


\begin{align*}
\frac{1}{2} \big\|{\Delta Y' D}\big\|_F^2 &\le \Big\langle\Delta_A,\overline{E}DY^\top\Big\rangle+\frac{\lambda}{2} \Bigg(3\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}-\big\|{(\Delta_UD)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}}}\big\|_{2,1}\Bigg).
\end{align*}

Using the Lemma~\ref{lem:chi-sq-dev} with $\mu= \left(1 \ 1 \ \dots \ 1\right)^\top$, we get
\begin{align*}
\ensuremath{\mathbb{P}} \left(\big\|{\eta_t}\big\|_2^2 \le n+2\sqrt{vn}+2v\right) \ge 1-e^{-v}.
\end{align*}
Letting $v=\log \left(\frac{T}{\delta}\right)$, and taking the union over $t = 2,\dots, T$ yields
\begin{align*}
\ensuremath{\mathbb{P}} \left(\max_{t \in \left\{{2,\dots,T}\right\}}\big\|{\eta_t}\big\|_2^2 \le n+2\sqrt{n\log \left(\frac{T}{\delta}\right)}+2\log \left(\frac{T}{\delta}\right)\right) 
\ge 1-\delta
\end{align*}
and taking the square root leads to 
\begin{align*}
\ensuremath{\mathbb{P}} &\bigg(\max_{t \in \left\{{2,\dots,T}\right\}}\big\|{\eta_t}\big\|_2 \le \sqrt{n}+\left(4n\log \left(\frac{T}{\delta}\right)\right)^{1/4}+\sqrt{2\log \left(\frac{T}{\delta}\right)}\bigg) \ge 1-\delta.
\end{align*}

Note that $\overline{E}$ can be written as follows:
\begin{align*}
\overline{E} &= \ensuremath{\begin{bmatrix} \eta_2 & \eta_3 & \dots & \eta_T \end{bmatrix}}_{n \times (T-1)}=\ensuremath{\begin{bmatrix} g_1^\top \\ \vdots \\ g_d^\top \end{bmatrix}}
\end{align*}
where $g_i \stackrel{\mathclap{\text{i.i.d}}}{\sim} \mathcal{N} \left(0,I_{T-1}\right)$. Therefore, 
\begin{align*}
\sup_{\big\|{b}\big\|_{\infty} \le r, \big\|{b}\big\|_0 \le \ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}} \big\|{\overline{E}b}\big\|_{\infty} &= \sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)} \max_{i \in [n]} \ensuremath{\left | g_i^\top b \right |}\\
&= \max_{i \in [n]} \sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)}  \ensuremath{\left | g_i^\top b \right |}.
\end{align*}
Now consider $\sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)}  \ensuremath{\left | g^\top b \right |}$ for $g {\sim} \mathcal{N} \left(0,I_{T-1}\right)$. We can see that bounding $\max_{i \in [n]} \sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)}  \ensuremath{\left | g_i^\top b \right |}$ can be achieved by finding an upper bound on $\sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)}  \ensuremath{\left | g^\top b \right |}$ and then applying union bound over $i \in [n]$. To this end, we show that the supremum function in question is Lipschitz and then use concentration bounds for Lipschitz functions of standard i.i.d Gaussian's to achieve the desired bound.  

\begin{remark}\label{rem:lipschitz-sup-gb}
Let $f(x) = \sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)} \ensuremath{\left | x^\top b \right |}$. We can see that $f(x)$ is Lipschitz over $\ensuremath{\mathbb{R}}$ with respect to $\big\|{\cdot}\big\|_2$ norm. This can be seen by observing,
\begin{align*}
\ensuremath{\left | f(x)-f(y) \right |} &\le \left(\sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)} \big\|{b}\big\|_2\right) \big\|{x-y}\big\|_2\\
&\le r\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |} \big\|{x-y}\big\|_2
\end{align*}
where the last inequality follows from the fact that $\big\|{b}\big\|_2 \le \big\|{b}\big\|_1 \le r\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}$ holds for all $b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)$.
\end{remark}

Given Remark~\ref{rem:lipschitz-sup-gb}, we obtain from Theorem~\ref{thm:bounded-func-conc} \cite[from Chapter 3]{Wainwright2019} that for any $q > 0$,


\begin{align*}
&\ensuremath{\mathbb{P}} \left(\ensuremath{\left | \sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)}  \ensuremath{\left | g^\top b \right |}-\ensuremath{\mathbb{E}}\left(\sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)}  \ensuremath{\left | g^\top b \right |}\right) \right |} \ge q\right) \le 2\exp\left(\frac{-cq^2}{r^2 \ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}^2}\right).
\end{align*}


Let $\mu \left(\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)\right) \coloneq \ensuremath{\mathbb{E}} \left(\sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)}  \ensuremath{\left | g^\top b \right |}\right)$ where we recall that $\mu \left(\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)\right)$ is known as the Gaussian complexity of $\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)$ \cite[see Section 7.5.3]{HDPbook}. This can be bounded in terms of the Gaussian width of $\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)$ as follows, see \cite[Lemma 7.5.11]{HDPbook}. 


$$\mu \left(\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)\right) \lesssim w \left(\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)\right)+\big\|{y}\big\|_2 \text{ for } y \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right).$$ 


Since $0 \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)$, we have,
\begin{align*}
\mu \left(\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)\right) \lesssim w \left(\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)\right).
\end{align*}

Therefore, with probability at least $ 1-2\exp \left(\frac{-cq^2}{r^2\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}^2}\right)$, 
\begin{align*}
\sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)}  \ensuremath{\left | g^\top b \right |} \le c_1 w \left(\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)\right)+q
\end{align*}
for some constant $c_1$. Letting $q = c_2 r \ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |} \sqrt{\log \left(\frac{n}{\delta}\right)}$ for an appropriate constant $c_2$, we get,
\begin{align*}
\ensuremath{\mathbb{P}} \bigg(\sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)}  \ensuremath{\left | g^\top b \right |} &\le c_1 w \left(\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)\right)+c_2 r \ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |} \sqrt{\log \left(\frac{n}{\delta}\right)}\bigg) \ge 1-\frac{\delta}{n}
\end{align*}
and taking the union bound over $i\in [n]$,
\begin{align*}
\ensuremath{\mathbb{P}} \bigg(\big\|{\overline{E}D_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}Y_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}^\top}\big\|_{\infty, \infty} &\le c\bigg( w \left(\ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)\right)+ r \ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |} \sqrt{\log \left(\frac{n}{\delta}\right)}\bigg)\bigg) \ge 1-\delta.
\end{align*}
Therefore, $\ensuremath{\mathbb{P}} \left(\ensuremath{\ensuremath{\mathcal{E}}_{1a}}\right) \ge 1-\delta$.

\label{rem:lipschitz-sup-gb}
Let $f(x) = \sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)} \ensuremath{\left | x^\top b \right |}$. We can see that $f(x)$ is Lipschitz over $\ensuremath{\mathbb{R}}$ with respect to $\big\|{\cdot}\big\|_2$ norm. This can be seen by observing,
\begin{align*}
\ensuremath{\left | f(x)-f(y) \right |} &\le \left(\sup_{b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)} \big\|{b}\big\|_2\right) \big\|{x-y}\big\|_2\\
&\le r\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |} \big\|{x-y}\big\|_2
\end{align*}
where the last inequality follows from the fact that $\big\|{b}\big\|_2 \le \big\|{b}\big\|_1 \le r\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}$ holds for all $b \in \ensuremath{\mathcal{B}}\left(r,\ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}\right)$.

Let $\eta = \operatorname{vec}\left(\ensuremath{\begin{bmatrix} \eta_1 & \eta_2 & \dots & \eta_T \end{bmatrix}}\right)$ and note that 
$x_t = \widetilde{A}(t) \eta$ where 


$$\widetilde{A}(t) :=\ensuremath{\begin{bmatrix} (A^*)^{t-1} & (A^*)^{t-2} & \dots & I_n & 0 & \dots & 0 \end{bmatrix}} \in \ensuremath{\mathbb{R}}^{n \times nT}.$$ 


For any $i\in [n]$, $x_{ti} = a^\top(t,i) \eta$ where $a^\top(t,i)$ is the $i$-th row of $\widetilde{A}(t)$ and $x_{ti}$ is the $i$-th element of $x_t$. Note that,
\begin{align*}
\ensuremath{\mathbb{E}} \left(x^2_{ti}\right) = \big\|{a(t,i)}\big\|_2^2 \le \big\|{\widetilde{A}(t)}\big\|_2^2. 
\end{align*}
For any $v=\operatorname{vec}\left(\ensuremath{\begin{bmatrix} v_1 & v_2 & \dots & v_T \end{bmatrix}}\right)$ with $\big\|{v}\big\|_2=1$,
\begin{align*}
\big\|{\widetilde{A}(t)v}\big\|_2 &= \big\|{\sum_{t=1}^T (A^*)^{t-i} v_i}\big\|_2 \le \sum_{t=1}^T \big\|{(A^*)^{t-i}}\big\|_2\le \sum_{t=1}^{\infty} \big\|{(A^*)^{t-i}}\big\|_2 \le J(A^*),
\end{align*}
and therefore, $\ensuremath{\mathbb{E}} \left(x^2_{ti}\right) \le J^2(A^*)$. 

