Let us denote,

\begin{align*}
\overline{P}_2 &= c_1J^2(A^*) \gamma_2\left(\widetilde{C}_{\ensuremath{\mathcal{K}}},\big\|{\cdot}\big\|_2\right)\bigg(\gamma_2\left(\widetilde{C}_{\ensuremath{\mathcal{K}}},\big\|{\cdot}\big\|_2\right)+1\bigg)+J^2(A^*)\\
\overline{F}_2 &= c_1 J^2(A^*) \left(\gamma_2\left(\widetilde{C}_{\ensuremath{\mathcal{K}}},\big\|{\cdot}\big\|_2\right)+1\right) \text{ and, } \overline{L}_2 = J^2(A^*)\\
\end{align*}
for sufficiently large $c_1>1$. Then from \eqref{eq:Mt-bnd-krah}, 
\begin{align*}
&\ensuremath{\mathbb{P}} \left(\sup_{M\in \ensuremath{\mathcal{M}}_t} \big\|{M\eta}\big\|_2^2 \le J^2(A^*)+c_2 \overline{P}_2+q\right) \ge 1-2\exp\left(-c_3 \min \left\{{\frac{q^2}{\overline{F}_2^2},\frac{q}{\overline{L}_2}}\right\}\right).
\end{align*}
Let $q = \overline{F}_2\sqrt{m}$ for $m \ge 1$. Since $\overline{F}_2 \ge \overline{L}_2$, we have $\min \left\{{\frac{q^2}{\overline{F}_2^2},\frac{q}{\overline{L}_2}}\right\} = \sqrt{m}$. Therefore, 
\begin{align*}
&\ensuremath{\mathbb{P}} \left(\sup_{M\in \ensuremath{\mathcal{M}}_t} \big\|{M\eta}\big\|_2^2 \le J(A^*)+c_2 \overline{P}_2+\overline{F}_2\sqrt{m}\right) \ge 1-2\exp\left(-c_3 \sqrt{m}\right).
\end{align*}
Recall from the proof of Lemma \ref{lem:lwr-bnd-deltaA} that 
\begin{align*}
\gamma_2\left(\widetilde{C}_{\ensuremath{\mathcal{K}}},\big\|{\cdot}\big\|_2\right) \lesssim \gamma_2\left(\widetilde{C}_{\ensuremath{\mathcal{K}}},\big\|{\cdot}\big\|_F\right)\asymp w\left(\widetilde{C}_{\ensuremath{\mathcal{K}}}\right) \lesssim \sqrt{k \log \left(\frac{n^2}{k}\right)}.
\end{align*}

Therefore letting $m=c\log^2 \left(\frac{1}{\delta}\right)$,
\begin{align*}
c_2 \overline{P}_2+\overline{F}_2\sqrt{m} & \le c' J^2(A^*) \Bigg(k\log \left(\frac{n^2}{k}\right)+\sqrt{k\log \left(\frac{n^2}{k}\right)}+\sqrt{m}+\sqrt{mk\log \left(\frac{n^2}{k}\right)}+1\Bigg)\\
&\le \overline{c} J^2(A^*) \Bigg(k\log \left(\frac{n^2}{k}\right)+\log \left(\frac{1}{\delta}\right)\sqrt{k\log \left(\frac{n^2}{k}\right)}\Bigg)\\
&\le \overline{c} J^2(A^*) k \log \left(\frac{n^2}{k}\right) \log \left(\frac{1}{\delta}\right) .
\end{align*}
 Therefore with probability at least $1-\delta$, $$\sup_{M \in \ensuremath{\mathcal{M}}_t} \big\|{M\eta}\big\|_2^2 \le \overline{c} J^2(A^*) k \log \left(\frac{n^2}{k}\right) \log \left(\frac{1}{\delta}\right)$$.  

 Note that this is for a fixed $t$. Taking union bound over $t \in [T]$ with an appropriate rescaling of $\delta$, we have that with probability at least $1-\delta$,


 \[
 \big\|{\Delta_A Y_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}} D_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}}}\big\|_{2,\infty} \le c J(A^*) \sqrt{k \log \left(\frac{n^2}{k}\right) \log \left(\frac{T}{\delta}\right)} \big\|{\Delta_A}\big\|_F.
  \]

Let $R=J(A^*) \sqrt{k \log \left(\frac{n^2}{k}\right) \log \left(\frac{T}{\delta}\right)}$. Combining the bounds on $\big\|{\Delta_A Y_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}} D_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}^c}}}\big\|_{2,\infty}$ and $\big\|{\Delta_A Y_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}} D_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,\infty}$, we get,
 \begin{align*}
\ensuremath{\left | \Big\langle\Delta_A Y D,\Delta_U D\Big\rangle \right |} & \le \big\|{(\Delta_U D)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1} 2r\sqrt{k} \big\|{\Delta_A}\big\|_F+\left(3\big\|{(\Delta_U D)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}+\frac{\overline{V}}{\overline{\lambda}} \big\|{\Delta_A}\big\|_F\right) c R \big\|{\Delta_A}\big\|_F \\
& \le c_1 \frac{\overline{V}}{\overline{\lambda}} R \big\|{\Delta_A}\big\|_F^2+c_2 r R\sqrt{k}\big\|{\Delta_A}\big\|_F \big\|{(\Delta_U D)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{2,1}\\
& \le \widetilde{c}_1 \frac{\overline{V}}{\overline{\lambda}} R \big\|{\Delta_A}\big\|_F^2+\widetilde{c}_2 r R\sqrt{k \ensuremath{\left | \ensuremath{\widetilde{\ensuremath{\mathcal{S}}}} \right |}}\big\|{\Delta_A}\big\|_F \big\|{(\Delta_U D)_{\ensuremath{\widetilde{\ensuremath{\mathcal{S}}}}}}\big\|_{F}.
\end{align*}

When $z_t \in \left\{{0,1}\right\}$ for $t \in \left\{{1,\dots, T}\right\}$ and $b_t \in \left\{{0,1}\right\}$ for $t \in \left\{{1,\dots, T-1}\right\}$, the constraint $b_t = z_t  z_{t+1}$ is equivalent to the set of constraints $b_t \le z_t, b_t \le z_{t+1}$ and $b_t \ge z_t+z_{t+1}-1$. To see this we can consider the possible values of $z_t$ and $z_{t+1}$.


\begin{itemize}
\item {\bf Case 1: ($z_t = z_{t+1}=1$)} The constraint $b_t \ge z_t+z_{t+1}-1=1+1-1=1$ implies $b_t = 1 = z_t \cdot z_{t+1}$.

\item {\bf Case 2: ($z_t=0$ or $z_{t+1}=0$)} The two constraints $b_t \le z_t$ and $b_t \le z_{t+1}$ imply $b_t \le \min\left\{{z_t,z_{t+1}}\right\} = 0$ which implies $b_t = 0 = z_t z_{t+1}$.
\end{itemize}
